import { test, expect } from '@playwright/test';

test.describe('In-App Notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display new notifications in real-time', async ({ page }) => {
    // Assume user is logged in and notifications are enabled
    await page.click(getByRole('button', { name: /login/i })); // Login action
    await page.fill(getByLabel('Username'), 'testuser');
    await page.fill(getByLabel('Password'), 'password');
    await page.click(getByRole('button', { name: /submit/i }));

    // Wait for the notifications section to be visible
    await expect(page.getByRole('region', { name: /notifications/i })).toBeVisible();

    // Simulate receiving a new notification
    await page.evaluate(() => {
      const event = new Event('newNotification');
      document.dispatchEvent(event);
    });

    // Check if the new notification appears
    await expect(page.getByText(/you have a new message/i)).toBeVisible();
  });

  test('should not show duplicate notifications', async ({ page }) => {
    await page.click(getByRole('button', { name: /login/i }));
    await page.fill(getByLabel('Username'), 'testuser');
    await page.fill(getByLabel('Password'), 'password');
    await page.click(getByRole('button', { name: /submit/i }));

    await expect(page.getByRole('region', { name: /notifications/i })).toBeVisible();

    // Simulate receiving the same notification twice
    await page.evaluate(() => {
      const event = new Event('newNotification');
      document.dispatchEvent(event);
      document.dispatchEvent(event);
    });

    // Check if the notification appears only once
    const notifications = await page.locator(getByText(/you have a new message/i)).count();
    expect(notifications).toBe(1);
  });
});
